import fs from 'node:fs/promises';import{db,send,asset,reviewed,task}from'./reply-runtime-explicit-card-resend-20261019.mjs';
const dir='artifacts/reply-review-20261019-weekend',rows=JSON.parse(await fs.readFile(dir+'/latest-reply-check.json')).rows;
const cards={'Fisher Song':'Fisher','SUKHWINDER KAUR':'Sukhwinder','STEPHEN T MILIC':'Stephen','Jodi Ramsden':'Jodi','Kim Bertling':'Kim','SUNNY GIROTI':'Sunny','Lesley Cross':'Lesley','FRED SKOGLAND':'Fred'};
const custom={'JAS SONI':"We provide a flat binding estimate for the agreed move, Jas. The cost depends on the items, route and access rather than one standard rate. Are you asking about a particular move or gathering information for future clients? - John",'NICHOLAS IP':"Happy to help, Nicholas. Is there a particular move you need an estimate for? If so, the pickup and destination towns and a rough idea of what's moving are a good starting point. - John",'MELODY MARTIN':"For a 2+1 townhouse, Melody, the cost can vary quite a bit with the furniture, boxes, distance and stairs. I don't want to give you a misleading figure based on bedroom count alone. If you have an example route and rough inventory, we can prepare an estimate for that example. - John","TARA D'OLIVEIRA":"Of course, Tara — our website is https://starmovers.ca. Please feel free to share it with your clients for their Belleville-to-Whitby move. - John"};
const plans=[];for(const r of rows){const c=r.contact,n=c.name;if(!cards[n]&&!custom[n])continue;let body=custom[n]||`Here you go, ${cards[n]}. Here's our ${c.city} digital card to save and share when a client needs moving help. You can call or text me here. - John`;if(n==='FRED SKOGLAND')body="Of course, Fred — I'm attaching the card image here so you can save it directly. - John";if(n==='STEPHEN T MILIC')body="Here you go, Stephen. Our website is https://starmovers.ca, and you can read customer reviews on our Google business page: https://g.page/r/CQN6C4RNFOJ0EAE. I've attached our Toronto card too. - John";plans.push({id:c.id,name:n,phone:c.phone,city:c.city,latest:r.thread[0].id,from:'+14374650584',body,media_urls:cards[n]?[await asset(c.city)]:[],explicit_card_resend_touch:n==='FRED SKOGLAND'?r.thread[0].id:undefined,followup_key:'20261019-1354',note:'Owner-approved requested reply; no invented price, availability or duplicated Sales qualification.'});}
await fs.writeFile(dir+'/1354-drafts.json',JSON.stringify(plans,null,2));const results=[];
const cayla=rows.find(r=>r.contact.name==='CAYLA MILANI');if(cayla){const[last]=await db('market_touches',{contact_id:'eq.'+cayla.contact.id,direction:'eq.inbound',order:'created_at.desc',limit:'1'});if(/^Inbound SMS:\s*Unsubscribe\s*$/i.test(last.notes)){await db('market_contacts',{id:'eq.'+cayla.contact.id},'PATCH',{do_not_contact:true,cross_channel_suppressed_at:new Date().toISOString(),cross_channel_suppression_reason:'recipient_explicit_stop_20261019',sequence_paused:true,sequence_paused_reason:'recipient_opt_out',next_follow_up:null,stage:'dnc',decision:'opted_out'});await db('sequence_jobs',{contact_id:'eq.'+cayla.contact.id,status:'eq.pending'},'PATCH',{status:'cancelled',error:'Recipient requested no further contact'});await reviewed(last.id,'Explicit unsubscribe honoured; no reply.');results.push({name:cayla.contact.name,state:'suppressed'});}}
for(const p of plans){try{const receipt=await send(p);if(receipt.state!=='accepted')throw Error('Ambiguous receipt');results.push({name:p.name,state:'accepted',sid:receipt.result.sid,card:p.media_urls.length>0});}catch(e){results.push({name:p.name,state:'held',error:String(e)});}await fs.writeFile(dir+'/1354-results.json',JSON.stringify(results,null,2));}
const handled=new Set(plans.map(p=>p.id));for(const r of rows){const t=r.thread[0];if(handled.has(r.contact.id)||t.direction!=='inbound'||t.metadata?.partnership_review?.reply_required===false||['CARMEN CHAN','CAYLA MILANI'].includes(r.contact.name))continue;const text=t.notes.replace(/^Inbound SMS:\s*/,'');if(!/^(thanks|thank you|thx|ty!|got it|ok thanks|okay great|perfect|liked|loved|👍|for sure, thanks|just general asking)/i.test(text))continue;const[last]=await db('market_touches',{contact_id:'eq.'+r.contact.id,order:'created_at.desc,id.desc',limit:'1'});if(last.id!==t.id)continue;await reviewed(t.id,'Acknowledgement/reaction or future information only; no additional response or current moving job.');await db('market_contacts',{id:'eq.'+r.contact.id},'PATCH',{sequence_paused:true,sequence_paused_reason:'human_managed_relationship',next_follow_up:null});results.push({name:r.contact.name,state:'reviewed_no_reply'});}
const taraTask='tara-handoff-20261019';const[t]=await db('crm_tasks',{id:'eq.'+taraTask});if(t)await db('crm_tasks',{id:'eq.'+taraTask},'PATCH',{description:t.description+'\nLatest update: Tara requested website for her clients to review. Website supplied in Partnerships. This is a client referral; allow client review and coordinate with Tara, without repeating qualification questions or contacting unidentified clients.'});
await fs.writeFile(dir+'/1354-results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));
